const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function evaluateAsync(obj) {
    return new Promise((resolve, reject) => {
      obj.evaluate(resolve, reject);
    });
  }

  try {
    // 1. Geometry & Time Definitions
    const ecoregions = ee.FeatureCollection('RESOLVE/ECOREGIONS/2017');
    const pantanal = ecoregions.filter(ee.Filter.eq('ECO_NAME', 'Pantanal')).geometry();
    const brazil = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
      .filter(ee.Filter.eq('country_na', 'Brazil'))
      .geometry();
    const region = pantanal.intersection(brazil, 100);

    // Helper: Aqua fire collection filtered to region and dates
    function getAquaFireCollection(start, end) {
      return ee.ImageCollection('MODIS/061/MYD14A1')
        .filterDate(start, end)
        .filterBounds(region);
    }

    // 2. Data Acquisition & Check
    const dayStart = '2024-06-11';
    const dayEnd = '2024-06-12';
    const col2024 = getAquaFireCollection(dayStart, dayEnd);
    const dayCount = await evaluateAsync(col2024.size());
    console.log(`Aqua MYD14A1 2024-06-11 images: ${dayCount}`);
    if (!dayCount || dayCount === 0) {
      console.log('No Aqua data for the target day in region.');
      console.log('C1');
      return;
    }

    // 3. Processing for target day
    const dayImg = col2024.mosaic().clip(region);
    const fireMask = dayImg.select('FireMask');
    const det2024Img = fireMask.eq(7).or(fireMask.eq(8)).or(fireMask.eq(9)).rename('det');

    const dayValidDict = await evaluateAsync(
      fireMask.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9,
      })
    );
    const dayDetDict = await evaluateAsync(
      det2024Img.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9,
      })
    );

    const validPx2024 = dayValidDict ? dayValidDict.FireMask || 0 : 0;
    const firePx2024 = dayDetDict ? dayDetDict.det || 0 : 0;

    console.log(`2024-06-11 valid px: ${validPx2024}, fire px: ${firePx2024}`);
    if (validPx2024 === 0) {
      console.log('No valid pixels after processing on target day.');
      console.log('C2');
      return;
    }
    if (firePx2024 === null || Number.isNaN(firePx2024)) {
      console.log('Calculation failure on target day.');
      console.log('C3');
      return;
    }

    // 4. Baseline (any June day 2000-2023) with Aqua
    const baseCol = getAquaFireCollection('2000-06-01', '2023-07-01');
    const baseImgCount = await evaluateAsync(baseCol.size());
    if (!baseImgCount || baseImgCount === 0) {
      console.log('Baseline Aqua collection has no images in June 2000-2023.');
      console.log('C1');
      return;
    }

    const baseDates = ee.List(baseCol.aggregate_array('system:time_start'))
      .map(function (t) { return ee.Date(t).format('YYYY-MM-dd'); })
      .distinct();
    const baseDaysCount = await evaluateAsync(baseDates.size());

    const perDayFC = ee.FeatureCollection(
      baseDates.map(function (d) {
        d = ee.String(d);
        const dc = baseCol.filterDate(ee.Date(d), ee.Date(d).advance(1, 'day'));
        const dm = dc.mosaic().clip(region);
        const fm = dm.select('FireMask');
        const det = fm.eq(7).or(fm.eq(8)).or(fm.eq(9)).rename('det');
        const detSum = ee.Number(det.reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: region,
          scale: 1000,
          maxPixels: 1e9,
        }).get('det'));
        return ee.Feature(null, { date: d, det: detSum });
      })
    );

    const maxFeature = ee.Feature(perDayFC.sort('det', false).first());
    const baseMaxDet = await evaluateAsync(maxFeature.get('det'));
    const baseMaxDate = await evaluateAsync(maxFeature.get('date'));

    if (baseMaxDet === null || Number.isNaN(baseMaxDet)) {
      console.log('Calculation failure on baseline.');
      console.log('C3');
      return;
    }

    console.log(`Baseline June 2000-2023: images=${baseImgCount}, days=${baseDaysCount}`);
    console.log(`Baseline max daily fire px: ${baseMaxDet} on ${baseMaxDate}`);
    console.log(`Compare 2024-06-11 vs baseline max: ${firePx2024} vs ${baseMaxDet}`);

    // 5. Final Answer
    const answer = (firePx2024 > baseMaxDet) ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
